    setEvents(undefined);
    setSelected(undefined);
    setDigest(undefined);
    if (!session) return;
    void loadSession(session, graphLevel);
    api.events(session).then((evs) => setEvents(new Map(evs.map((e) => [e.id, e])))).catch(() => undefined);
    const p = new URLSearchParams(location.search);
