{"file_path":"$PROJECT/code/packages/ui/src/FilterBar.tsx","content":"import { useEffect, useRef, useState } from "react";
import type { FilterCode } from "@yolo-twice/analyzers/search";

/** Chip codes in display order. Codes are OR'd; tool chips live in the tools menu. */
export const CHIPS: { code: FilterCode; label: string; title: string }[] = [
  { code: "u", label: "user", title: "your prompts (subagent briefs excluded)" },
  { code: "a", label: "assistant", title: "assistant text" },
  { code: "h", label: "thinking", title: "thinking blocks" },
  { code: "t", label: "tools", title: "every tool call and result" },
  { code: "e", label: "errors", title: "tool calls that failed" },
  { code: "s", label: "subagents", title: "everything subagents did" },
  { code: "c", label: "compactions", title: "compactions and slash commands" },
  { code: "r", label: "rewinds", title: "turns on a rewound branch" },
];

/**
 * Query and filters. They never narrow the view: matches are highlighted in every view and the
 * rest is dimmed. An empty query with a filter lists every match, e.g. all your prompts.
 */
export function FilterBar(props: {
  q: string;
  k: FilterCode[];
  tools: string[];
  matches: number;
  scopeLabel: string;
  onQuery: (q: string) => void;
  onCodes: (k: FilterCode[]) => void;
}) {
  const input = useRef<HTMLInputElement>(null);
  const [draft, setDraft] = useState(props.q);
  useEffect(() => setDraft(props.q), [props.q]);
  // typing is debounced into the URL so history is not spammed and the views stay calm
  useEffect(() => {
    if (draft === props.q) return;
    const t = setTimeout(() => props.onQuery(draft), 150);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [draft]);

  // "/" focuses the query box from anywhere
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const t = e.target as HTMLElement;
      if (e.key === "/" && !/input|textarea|select/i.test(t.tagName)) {
        e.preventDefault();
        input.current?.focus();
      }
    };
    addEventListener("keydown", onKey);
    return () => removeEventListener("keydown", onKey);
  }, []);

  const toggle = (code: FilterCode) => props.onCodes(props.k.includes(code) ? props.k.filter((c) => c !== code) : [...props.k, code]);
  const toolCodes = props.k.filter((c) => c.startsWith("t:"));
  const active = Boolean(props.q) || props.k.length > 0;

  return (
    <div className="filterbar">
      <input
        ref={input}
        className="query"
        placeholder={`search ${props.scopeLabel}…  (press /)`}
        value={draft}
        onChange={(e) => setDraft(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === "Escape") {
            if (draft) setDraft("");
            (e.target as HTMLInputElement).blur();
            e.stopPropagation();
          }
        }}
        aria-label="search"
      />
      <div className="chips" role="group" aria-label="filters">
        {CHIPS.map((c) => (
          <button key={c.code} className={`chip ${props.k.includes(c.code) ? "on" : ""}`} title={c.title} onClick={() => toggle(c.code)} aria-pressed={props.k.includes(c.code)}>
            {c.label}
          </button>
        ))}
        {props.tools.length > 0 && (
          <details className="tools-menu">
            <summary className={`chip ${toolCodes.length ? "on" : ""}`}>{toolCodes.length ? toolCodes.map((c) => c.slice(2)).join(", ") : "tool ▾"}</summary>
            <div className="menu">
              {props.tools.map((t) => {
                const code = `t:${t}` as FilterCode;
                return (
                  <label key={t}>
                    <input type="checkbox" checked={props.k.includes(code)} onChange={() => toggle(code)} /> {t}
                  </label>
                );
              })}
            </div>
          </details>
        )}
      </div>
      <span className="match-count" aria-live="polite">
        {active ? `${props.matches} match${props.matches === 1 ? "" : "es"} in ${props.scopeLabel}` : ""}
      </span>
      {active && (
        <button className="clear" onClick={() => (setDraft(""), props.onQuery(""), props.onCodes([]))} title="clear query and filters">
          clear
        </button>
      )}
    </div>
  );
}
"}

{"file_path":"$PROJECT/code/packages/ui/src/Timeline.tsx","content":"import { useRef, useState } from "react";
import { fmtDuration, fmtTime, walk, type StructureNode } from "./api";

export interface Bar {
  id: string;
  label: string;
  start: number; // ms epoch
  end: number;
  node?: StructureNode;
  /** Phase id, to draw boundaries between groups of turns. */
  group?: string;
}

export interface Tick {
  id: string;
  ts: number;
  kind: string;
}

const KIND_COLOUR: Record<string, string> = {
  "user.prompt": "var(--turn)",
  "user.command": "var(--turn)",
  "assistant.text": "var(--fg)",
  "assistant.thinking": "var(--muted)",
  "tool.call": "var(--tool)",
  "tool.result": "var(--tool)",
  compaction: "var(--branch)",
};

function barColour(b: Bar): string {
  const n = b.node;
  if (!n) return "var(--turn)";
  if (n.meta?.branch) return "var(--branch)";
  if (n.meta?.step_kind === "tool-error") return "var(--error)";
  if (n.meta?.step_kind === "subagent") return "var(--agent)";
  const kinds = [...walk(n)].map((x) => x.meta?.step_kind);
  if (kinds.includes("tool-error")) return "var(--error)";
  if (kinds.includes("subagent")) return "var(--agent)";
  return "var(--turn)";
}

/**
 * The scrubber: one strip of bars (sessions, turns or steps, whatever the focus contains) on an
 * axis spanning the focus, hit ticks underneath, and a brush. Drag to set a window, which snaps to
 * whole bars; click a bar to select it, double click to focus it; click empty space to clear.
 */
export function Timeline(props: {
  bars: Bar[];
  ticks: Tick[];
  start: number;
  end: number;
  window?: [number, number]; // seconds from start, already snapped
  selected?: string;
  hover?: string;
  dim: Set<string>;
  hits: Map<string, number>;
  onSelect: (id: string) => void;
  onFocus: (id: string) => void;
  onWindow: (w: [number, number] | undefined) => void;
  onHover: (id: string | undefined) => void;
}) {
  const svg = useRef<SVGSVGElement>(null);
  const [drag, setDrag] = useState<{ a: number; b: number } | undefined>();
  const [tip, setTip] = useState<{ bar: Bar; x: number; y: number } | undefined>();
  const W = 1000;
  const LANE = 26;
  const TICKS = 10;
  const H = LANE + TICKS + 22;
  const span = Math.max(props.end - props.start, 1000);
  const x = (t: number) => ((t - props.start) / span) * W;
  const sec = (px: number) => (px / W) * (span / 1000);

  const toX = (e: React.MouseEvent) => {
    const r = svg.current!.getBoundingClientRect();
    return Math.min(W, Math.max(0, ((e.clientX - r.left) / r.width) * W));
  };

  const onDown = (e: React.MouseEvent) => {
    if ((e.target as Element).closest(".tl-bar")) return;
    const px = toX(e);
    setDrag({ a: px, b: px });
  };
  const onMove = (e: React.MouseEvent) => drag && setDrag({ ...drag, b: toX(e) });
  const onUp = () => {
    if (!drag) return;
    const [a, b] = [Math.min(drag.a, drag.b), Math.max(drag.a, drag.b)];
    setDrag(undefined);
    if (b - a < 4) return props.onWindow(undefined); // a click on empty space clears the window
    props.onWindow([Math.floor(sec(a)), Math.ceil(sec(b))]);
  };

  const groups: { id: string; x: number }[] = [];
  props.bars.forEach((b, i) => {
    if (i > 0 && b.group && b.group !== props.bars[i - 1]!.group) groups.push({ id: b.group, x: x(b.start) });
  });

  return (
    <div className="timeline">
      <svg
        ref={svg}
        viewBox={`0 0 ${W} ${H}`}
        preserveAspectRatio="none"
        width="100%"
        height={H}
        role="img"
        aria-label="timeline of the focus; drag to set a window"
        onMouseDown={onDown}
        onMouseMove={onMove}
        onMouseUp={onUp}
        onMouseLeave={() => (drag && onUp(), setTip(undefined))}
      >
        <rect x={0} y={0} width={W} height={LANE + TICKS} className="tl-bg" />
        {props.window && <rect x={x(props.start + props.window[0] * 1000)} y={0} width={x(props.start + props.window[1] * 1000) - x(props.start + props.window[0] * 1000)} height={LANE + TICKS} className="tl-window" />}
        {groups.map((g) => (
          <line key={g.id} x1={g.x - 1} x2={g.x - 1} y1={0} y2={LANE} className="tl-group" />
        ))}
        {props.bars.map((b) => {
          const bx = x(b.start);
          const bw = Math.max(x(b.end) - bx, 2);
          const cls = ["tl-bar", b.id === props.selected ? "selected" : "", b.id === props.hover ? "hover" : "", props.dim.has(b.id) ? "dim" : "", props.hits.has(b.id) ? "hit" : ""].join(" ");
          return (
            <rect
              key={b.id}
              data-id={b.id}
              x={bx}
              y={4}
              width={bw}
              height={LANE - 8}
              rx={2}
              fill={barColour(b)}
              className={cls}
              onClick={() => props.onSelect(b.id)}
              onDoubleClick={() => props.onFocus(b.id)}
              onMouseEnter={(e) => (props.onHover(b.id), setTip({ bar: b, x: e.clientX, y: e.clientY }))}
              onMouseLeave={() => (props.onHover(undefined), setTip(undefined))}
            />
          );
        })}
        {props.ticks.map((t) => (
          <rect key={t.id} x={x(t.ts) - 0.75} y={LANE} width={1.5} height={TICKS} fill={KIND_COLOUR[t.kind] ?? "var(--accent)"} className="tl-tick" />
        ))}
        {drag && <rect x={Math.min(drag.a, drag.b)} y={0} width={Math.abs(drag.b - drag.a)} height={LANE + TICKS} className="tl-brush" />}
        <text x={2} y={H - 6} className="tl-axis-label">
          {fmtTime(new Date(props.start).toISOString())}
        </text>
        <text x={W - 2} y={H - 6} className="tl-axis-label" textAnchor="end">
          {fmtTime(new Date(props.end).toISOString())} · {fmtDuration(props.end - props.start)}
        </text>
      </svg>
      {tip && (
