{"file_path":"$PROJECT/code/packages/ui/src/kinds.tsx","content":"import type { CSSProperties } from "react";
import { Archive, Bot, Brain, Disc3, FolderGit2, Layers, MessageSquareText, Reply, SquareSlash, TriangleAlert, Undo2, User, Wrench, type LucideIcon } from "lucide-react";
import type { Event, StructureNode } from "./api";

/**
 * One icon, one colour and one name per kind of thing in a session. The reader, the tape, the
 * graph legend and the filter chips all draw from here, so a tool call looks the same everywhere.
 */
export type Kind = "project" | "session" | "phase" | "you" | "command" | "text" | "think" | "tool" | "error" | "agent" | "compaction" | "rewind" | "result";

export const KIND: Record<Kind, { icon: LucideIcon; label: string; color: string }> = {
  project: { icon: FolderGit2, label: "Project", color: "var(--ink-2)" },
  session: { icon: Disc3, label: "Session", color: "var(--ink)" },
  phase: { icon: Layers, label: "Phase", color: "var(--ink-2)" },
  you: { icon: User, label: "You", color: "var(--k-you)" },
  command: { icon: SquareSlash, label: "Command", color: "var(--k-system)" },
  text: { icon: MessageSquareText, label: "Claude", color: "var(--k-text)" },
  think: { icon: Brain, label: "Thinking", color: "var(--k-think)" },
  tool: { icon: Wrench, label: "Tool", color: "var(--k-tool)" },
  error: { icon: TriangleAlert, label: "Error", color: "var(--k-error)" },
  agent: { icon: Bot, label: "Subagent", color: "var(--k-agent)" },
  compaction: { icon: Archive, label: "Compaction", color: "var(--k-system)" },
  rewind: { icon: Undo2, label: "Rewind", color: "var(--k-rewind)" },
  result: { icon: Reply, label: "Result", color: "var(--k-text)" },
};

const STEP: Record<string, Kind> = {
  prompt: "you",
  queued: "you",
  command: "command",
  text: "text",
  thinking: "think",
  tool: "tool",
  "tool-error": "error",
  subagent: "agent",
  compaction: "compaction",
  result: "result",
};

export function nodeKind(n: StructureNode): Kind {
  if (n.kind === "session") return "session";
  if (n.kind === "phase") return "phase";
  if (n.meta?.branch) return "rewind";
  if (n.kind === "turn") return n.meta?.step_kind === "command" ? "command" : "you";
  return STEP[n.meta?.step_kind ?? ""] ?? "text";
}

export function eventKind(e: Event): Kind {
  switch (e.kind) {
    case "user.prompt":
      return "you";
    case "user.command":
      return "command";
    case "assistant.thinking":
      return "think";
    case "tool.call":
      return "tool";
    case "tool.result":
      return e.data?.is_error ? "error" : "tool";
    case "subagent.start":
    case "subagent.stop":
      return "agent";
    case "compaction":
      return "compaction";
    default:
      return "text";
  }
}

/** Sets `--k` for CSS that tints icons, badges and graph nodes by kind. */
export function kindStyle(k: Kind): CSSProperties {
  return { "--k": KIND[k].color } as CSSProperties;
}

export function KindIcon({ kind, size = 14, className }: { kind: Kind; size?: number; className?: string }) {
  const Icon = KIND[kind].icon;
  return <Icon size={size} strokeWidth={2} className={className} aria-hidden />;
}

/** Inline `code` in summaries and prompts, rendered as code; everything else stays text. */
export function richText(text: string, mark?: string): (string | React.ReactElement)[] {
  const parts = text.split(/(`[^`\n]+`)/g);
  const out: (string | React.ReactElement)[] = [];
  parts.forEach((p, i) => {
    if (p.startsWith("`") && p.endsWith("`") && p.length > 2) out.push(<code key={i}>{p.slice(1, -1)}</code>);
    else if (p) out.push(...highlight(p, mark, i));
  });
  return out;
}

function highlight(text: string, mark: string | undefined, key: number): (string | React.ReactElement)[] {
  const term = mark?.trim();
  if (!term || term.length < 2) return [text];
  const re = new RegExp(`(${term.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")})`, "gi");
  return text.split(re).map((p, i) => (i % 2 ? <mark key={`${key}.${i}`}>{p}</mark> : p));
}
"}

{"file_path":"$PROJECT/code/packages/ui/src/Graph.tsx","content":"import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { mount, register } from "pele/core";
import flowchart from "pele/diagrams/flowchart";
import { Maximize, Minus, Plus, Scan } from "lucide-react";
import { KIND, kindStyle, type Kind } from "./kinds";

register(flowchart); // only the flowchart renderer: keeps the bundle small

const safe = (id: string) => id.replace(/[^A-Za-z0-9_]/g, "_");

/** The committed mermaid carries light-mode colours for other renderers; here CSS colours nodes by their class. */
const unstyled = (mermaid: string) =>
  mermaid
    .split("\n")
    .filter((l) => !/^\s*classDef\s/.test(l))
    .join("\n");

const MIN = 0.2;
const MAX = 2.5;
/** Text stays readable on first sight: fit the width, but never shrink below this or blow up past 1:1. */
const READABLE = 0.72;
const PAD = 28;

export interface HoverInfo {
  id: string;
  x: number;
  y: number;
}

/**
 * The map: mermaid text rendered by pele on a pannable, zoomable canvas. Drag or scroll to move,
 * ctrl/⌘ + scroll or pinch to zoom, a click zooms into a node (semantic zoom: the graph is redrawn
 * for it). Text is never scaled above 1:1, so a small graph does not shout and a large one stays legible.
 */
export function Graph(props: {
  mermaid: string;
  /** Every structure id that may appear in the graph. */
  ids: string[];
  selected?: string;
  /** Follow mode: keep the selected (newest) node centred. */
  follow?: boolean;
  hover?: string;
  dim: Set<string>;
  hits: Map<string, number>;
  /** Kinds present, for the legend. */
  legend: Kind[];
  onFocus: (id: string) => void;
  onHover: (h: HoverInfo | undefined) => void;
}) {
  const host = useRef<HTMLDivElement>(null);
  const view = useRef({ scale: 1, x: PAD, y: PAD, w: 0, h: 0 });
  const [zoom, setZoom] = useState(1);
  const drag = useRef<{ x: number; y: number; moved: number; id: number } | undefined>(undefined);
  const suppressClick = useRef(false);

  const idMap = useMemo(() => {
    const m = new Map<string, string>();
    for (const id of props.ids) {
      m.set(safe(id), id);
      m.set(`${safe(id)}_box`, id); // subagent clusters
    }
    return m;
  }, [props.ids]);

  const svg = () => host.current?.querySelector<SVGSVGElement>(":scope > svg") ?? null;

  const apply = useCallback((animate = false) => {
    const el = host.current;
    const s = svg();
    if (!el || !s) return;
    const v = view.current;
    el.classList.toggle("animate", animate);
    s.style.width = `${v.w * v.scale}px`;
    s.style.height = `${v.h * v.scale}px`;
    s.style.transform = `translate(${v.x}px, ${v.y}px)`;
    setZoom(v.scale);
  }, []);

  /** Keep at least a corner of the graph on screen. */
  const clamp = () => {
    const el = host.current;
    if (!el) return;
    const v = view.current;
    const gw = v.w * v.scale;
    const gh = v.h * v.scale;
    const keep = 80;
    v.x = Math.min(el.clientWidth - keep, Math.max(keep - gw, v.x));
    v.y = Math.min(el.clientHeight - keep, Math.max(keep - gh, v.y));
  };

