{"file_path":"$PROJECT/code/packages/ui/src/FilterBar.tsx","content":"import { useEffect, useRef, useState } from "react";
import { ChevronDown, Search, X } from "lucide-react";
import type { FilterCode } from "@yolo-twice/analyzers/search";
import { DropdownMenu, DropdownMenuCheckboxItem, DropdownMenuContent, DropdownMenuLabel, DropdownMenuSeparator, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { Kbd } from "@/components/ui/kbd";
import { KIND, kindStyle, type Kind } from "./kinds";
import { Tip } from "./Tip";

/** Chip codes in display order. Codes are OR'd; tool chips live in the tools menu. */
export const CHIPS: { code: FilterCode; kind: Kind; label: string; title: string }[] = [
  { code: "u", kind: "you", label: "You", title: "Your prompts (subagent briefs excluded)" },
  { code: "a", kind: "text", label: "Claude", title: "What Claude wrote" },
  { code: "h", kind: "think", label: "Thinking", title: "Thinking blocks" },
  { code: "t", kind: "tool", label: "Tools", title: "Every tool call and result" },
  { code: "e", kind: "error", label: "Errors", title: "Tool calls that failed" },
  { code: "s", kind: "agent", label: "Subagents", title: "Everything subagents did" },
  { code: "c", kind: "compaction", label: "Compactions", title: "Compactions and slash commands" },
  { code: "r", kind: "rewind", label: "Rewinds", title: "Turns on a rewound branch" },
];

/**
 * Query and filters. They never narrow the view: matches are highlighted in every view and the
 * rest is dimmed. An empty query with a filter lists every match, e.g. all your prompts.
 */
export function FilterBar(props: {
  q: string;
  k: FilterCode[];
  tools: string[];
  matches: number;
  scopeLabel: string;
  onQuery: (q: string) => void;
  onCodes: (k: FilterCode[]) => void;
}) {
  const input = useRef<HTMLInputElement>(null);
  const [draft, setDraft] = useState(props.q);
  useEffect(() => setDraft(props.q), [props.q]);
  // typing is debounced into the URL so history is not spammed and the views stay calm
  useEffect(() => {
    if (draft === props.q) return;
    const t = setTimeout(() => props.onQuery(draft), 150);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [draft]);

  // "/" focuses the query box from anywhere
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const t = e.target as HTMLElement;
      if (e.key === "/" && !/input|textarea|select/i.test(t.tagName)) {
        e.preventDefault();
        input.current?.focus();
      }
    };
    addEventListener("keydown", onKey);
    return () => removeEventListener("keydown", onKey);
  }, []);

  const toggle = (code: FilterCode) => props.onCodes(props.k.includes(code) ? props.k.filter((c) => c !== code) : [...props.k, code]);
  const toolCodes = props.k.filter((c) => c.startsWith("t:"));
  const active = Boolean(props.q) || props.k.length > 0;
  const ToolIcon = KIND.tool.icon;

  return (
    <div className="filterbar">
      <div className="search">
        <Search size={15} aria-hidden />
        <input
          ref={input}
          className="query"
          placeholder={`Search ${props.scopeLabel}`}
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Escape") {
              if (draft) setDraft("");
              (e.target as HTMLInputElement).blur();
              e.stopPropagation();
            }
          }}
          aria-label="Search"
        />
        {!draft && <Kbd>/</Kbd>}
      </div>
      <div className="chips" role="group" aria-label="Filters">
        {CHIPS.map((c) => {
          const Icon = KIND[c.kind].icon;
          const on = props.k.includes(c.code);
          return (
            <Tip key={c.code} label={c.title}>
              <button className={`chip ${on ? "on" : ""}`} style={kindStyle(c.kind)} onClick={() => toggle(c.code)} aria-pressed={on}>
                <Icon aria-hidden />
                {c.label}
              </button>
            </Tip>
          );
        })}
        {props.tools.length > 0 && (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <button className={`chip ${toolCodes.length ? "on" : ""}`} style={kindStyle("tool")}>
                <ToolIcon aria-hidden />
                {toolCodes.length ? toolCodes.map((c) => c.slice(2)).join(", ") : "Tool"}
                <ChevronDown aria-hidden />
              </button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="start" className="max-h-80 min-w-48">
              <DropdownMenuLabel>Only these tools</DropdownMenuLabel>
              <DropdownMenuSeparator />
              {props.tools.map((t) => {
                const code = `t:${t}` as FilterCode;
                return (
                  <DropdownMenuCheckboxItem key={t} checked={props.k.includes(code)} onCheckedChange={() => toggle(code)} onSelect={(e) => e.preventDefault()} className="font-mono text-[13px]">
                    {t}
                  </DropdownMenuCheckboxItem>
                );
              })}
            </DropdownMenuContent>
          </DropdownMenu>
        )}
      </div>
      <span className="match-count" aria-live="polite">
        {active ? `${props.matches} match${props.matches === 1 ? "" : "es"} in ${props.scopeLabel}` : ""}
      </span>
      {active && (
        <button className="chip" onClick={() => (setDraft(""), props.onQuery(""), props.onCodes([]))}>
          <X aria-hidden />
          Clear
        </button>
      )}
    </div>
  );
}
"}

{"file_path":"$PROJECT/code/packages/ui/src/Header.tsx","content":"import { BookOpen, BookOpenText, ChevronRight, Columns2, GitCommitHorizontal, ListRestart, Network, Pin, PinOff, Radio, SlidersHorizontal } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Slider } from "@/components/ui/slider";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";
import { ATTENTION, ATTENTION_LABEL, fmtDuration, fmtTime, type Attention, type AutoCommit, type Config, type StructureNode } from "./api";
import { KIND } from "./kinds";
import type { Layout } from "./state";
import { Tip } from "./Tip";

/** Rough cost table per detent: summarization calls per turn, and how far the view lags the session. */
const COST: Record<Attention, { callsPerTurn: number; lag: string }> = {
  micro: { callsPerTurn: 3, lag: "seconds" },
  attentive: { callsPerTurn: 1, lag: "about one turn" },
  balanced: { callsPerTurn: 0.25, lag: "about one phase" },
  yolo: { callsPerTurn: 0, lag: "only on demand" },
};

export interface Crumb {
  id: string;
  label: string;
}

/** Two reels: a recorder for agent sessions. */
function BrandMark() {
  return (
    <svg className="brand-mark" viewBox="0 0 22 22" aria-hidden>
      <rect x="0.5" y="2.5" width="21" height="17" rx="4.5" fill="var(--ink)" />
      <circle cx="7" cy="11" r="3.2" fill="none" stroke="var(--paper)" strokeWidth="1.6" />
      <circle cx="15" cy="11" r="3.2" fill="none" stroke="var(--paper)" strokeWidth="1.6" />
      <circle cx="15" cy="11" r="1.1" fill="var(--rec)" />
    </svg>
  );
}

/**
 * One row: where you are (project ▸ session ▸ focus path, mirroring the URL), whether the session
 * is live and followed, which views are shown, and the quieter settings behind one button.
 */
export function Header(props: {
  project: string;
  session?: { id: string; label: string; pinned: boolean };
  path: Crumb[]; // focus path inside the session, excluding the session itself
  canReset: boolean;
  onProject: () => void;
  onSessionRoot: () => void;
  onCrumb: (id: string) => void;
  onPin: (pinned: boolean) => void;
  onReset: () => void;
  follow: boolean;
  unseen: number;
  onFollow: (follow: boolean) => void;
  layout: Layout;
  onLayout: (l: Layout) => void;
  live: "connecting" | "live" | "offline";
  config?: Config;
  structure?: StructureNode;
  onAttention: (a: Attention) => void;
  autoCommit?: AutoCommit;
  onAutoCommit: (enabled: boolean) => void;
  onCatchMeUp: () => void;
}) {
  const attention = props.config?.attention ?? "balanced";
  const idx = ATTENTION.indexOf(attention);
  const turns = props.structure ? props.structure.children.reduce((n, p) => n + p.children.length, 0) : 0;
  const durationMs = props.structure ? Date.parse(props.structure.span.ts_last) - Date.parse(props.structure.span.ts_first) : 0;
  const hours = Math.max(durationMs / 3_600_000, 1 / 60);
  const callsPerHour = Math.round((turns * COST[attention].callsPerTurn) / hours);
  const pinned = props.session?.pinned;
  const ac = props.autoCommit;
  const ProjectIcon = KIND.project.icon;
  const SessionIcon = KIND.session.icon;
  const liveLabel = props.live === "live" ? "Live" : props.live === "offline" ? "Engine offline" : "Connecting";

  return (
    <header className="header">
      <span className="brand">
        <BrandMark />
        <span className="brand-name">yolo-twice</span>
      </span>
      <nav className="crumbs" aria-label="Focus">
        <ChevronRight size={14} className="crumb-sep" aria-hidden />
        {pinned ? (
          <Tip label="The session is pinned. Unpin it to browse the whole project.">
            <span className="crumb">
              <ProjectIcon size={15} aria-hidden />
              <span>{props.project}</span>
            </span>
          </Tip>
        ) : (
          <button className={`crumb ${props.session ? "" : "current"}`} onClick={props.onProject} title="All sessions of this project">
            <ProjectIcon size={15} aria-hidden />
            <span>{props.project || "Project"}</span>
          </button>
        )}
        {props.session && (
          <>
            <ChevronRight size={14} className="crumb-sep" aria-hidden />
            <span className="crumb-wrap">
              <button className={`crumb ${props.path.length ? "" : "current"}`} onClick={props.onSessionRoot} title={props.session.id}>
                <SessionIcon size={15} aria-hidden />
                <span>{props.session.label}</span>
              </button>
            </span>
            <Tip label={pinned ? "Pinned: Esc and reset stay inside this session. Click to unpin." : "Go into this session: pin it as the root."}>
              <Button variant="ghost" size="icon-sm" className={`pin ${pinned ? "on" : ""} size-7 text-ink-3`} onClick={() => props.onPin(!pinned)} aria-pressed={pinned} aria-label={pinned ? "Unpin the session" : "Pin the session"}>
                {pinned ? <Pin className="size-3.5" /> : <PinOff className="size-3.5" />}
              </Button>
            </Tip>
          </>
        )}
        {props.path.map((c, i) => (
          <span key={c.id} className="crumb-wrap">
            <ChevronRight size={14} className="crumb-sep" aria-hidden />
            <button className={`crumb ${i === props.path.length - 1 ? "current" : ""}`} onClick={() => props.onCrumb(c.id)} title={c.label}>
              <span>{c.label}</span>
            </button>
          </span>
        ))}
        {props.canReset && (
          <Tip label="Back to the top, and clear the time window. Esc goes up one level.">
            <Button variant="ghost" size="icon-sm"
[... truncated 3552 chars, sha256 0d47da5b1c746197 ...]
ession ran ${fmtDuration(durationMs)}.` : "."}
            </p>
            {ac && (
              <div className="border-t pt-3">
                <div className="flex items-center justify-between gap-3">
                  <span className="flex items-center gap-2 text-[13px] font-semibold">
                    <GitCommitHorizontal className="size-4" />
                    Auto-commit
                  </span>
                  <Button variant={ac.enabled ? "default" : "outline"} size="xs" className={`autocommit ${ac.enabled ? "on" : ""}`} onClick={() => props.onAutoCommit(!ac.enabled)} aria-pressed={ac.enabled}>
                    {ac.enabled ? "On" : "Off"}
                  </Button>
                </div>
                <p className="mt-1 text-[12.5px] leading-snug text-ink-2">
                  {ac.enabled
                    ? [
                        `Commits only .yolo-twice every ${Math.round(ac.intervalMs / 60_000)} minutes while it changes.`,
                        ac.lastCommit ? `Last commit ${ac.lastCommit.sha} at ${fmtTime(ac.lastCommit.ts)}.` : "No commit yet.",
                        ac.next ? `Next check ${new Date(ac.next).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}.` : "",
                        ac.skipped ? `Last check skipped: ${ac.skipped}.` : "",
                      ]
                        .filter(Boolean)
                        .join(" ")
                    : "Commit the .yolo-twice folder now and every 10 minutes, so it stops cluttering git status. Your staged work is left alone. Stays on until the engine restarts."}
                </p>
              </div>
            )}
          </div>
        </PopoverContent>
      </Popover>

      <Button size="sm" onClick={props.onCatchMeUp} disabled={!props.session}>
        <BookOpenText />
        <span className="hide-narrow">Catch me up</span>
      </Button>
    </header>
  );
}
